  f.str = strs[0].s; f.exact = strs[0].exact; f.star = strs[0].star;
  if (isChange) {
    if (strs.length < 2) return { error: 'No CHANGE string' };
    f.to = strs[1].s;
  }
  if (strs.length > need) return { error: 'Extraneous data on command' };
