        if (k.ch === 'p') return this.resolvePending(s, { type: 'cmd', cmd: 'SWAP PREV' });
        if (k.ch === 'r') return this.resolvePending(s, { type: 'cmd', cmd: 'RETRIEVE' });
        if (k.ch === 'l') { this.terminal.invalidate(); return this.render(); }
