        if (!s.retrieve.length) { setMsg('', 'Retrieve stack is empty.', 'N'); return true; }
        if (/^\d+$/.test(rest.trim())) s.retrievePos = Math.min(s.retrieve.length - 1, +rest.trim() - 1);
        else if (verb === 'RETF') s.retrievePos = s.retrievePos <= 0 ? s.retrieve.length - 1 : s.retrievePos - 1;
        else s.retrievePos = (s.retrievePos + 1) % s.retrieve.length;
